const quote = (value) => JSON.stringify(value);

/**
 * Render a vitest skeleton. Cases are `it.todo` placeholders and are not run.
 */
export const renderSkeleton = (spec) => {
  const cases =
    spec.acceptanceTests.length > 0
      ? spec.acceptanceTests
      : [`specify acceptance tests for ${spec.name}`];
  const body = cases.map((name) => `  it.todo(${quote(name)});`).join("\n");
  return [
    'import { describe, it } from "vitest";',
    "",
    "// Generated by build-from-text from plain text.",
    "// These cases are skeletons. The generator has not run them.",
    `describe(${quote(spec.name)}, () => {`,
    body,
    "});",
    "",
  ].join("\n");
};
